// Shipping Configuration
// Origin location: Parepare, Sulawesi Selatan

// TODO: Find your exact subdistrict_id from RajaOngkir
// You can get this by:
// 1. GET /api/rajaongkir/provinces -> find Sulawesi Selatan province_id
// 2. GET /api/rajaongkir/cities?province_id={id} -> find Parepare city_id
// 3. GET /api/rajaongkir/subdistricts?city_id={id} -> find your subdistrict_id

export const ORIGIN_SUBDISTRICT_ID = 5505; // TEMPORARY - Replace with actual Parepare subdistrict ID

// Default weight per product (in grams)
// If products don't have weight field, this will be used
export const DEFAULT_PRODUCT_WEIGHT = 500;

// Available couriers
export const COURIERS = [
  { code: 'jne', name: 'JNE' },
  { code: 'tiki', name: 'TIKI' },
  { code: 'pos', name: 'POS Indonesia' },
  { code: 'jnt', name: 'J&T Express' },
  { code: 'sicepat', name: 'SiCepat' },
  { code: 'anteraja', name: 'AnterAja' },
];
